{"command": "python - <<'PY'
from __future__ import annotations

import re
from datetime import date
from decimal import Decimal, InvalidOperation
from pathlib import Path

from PIL import Image, ImageOps
import pytesseract
from openpyxl import Workbook, load_workbook

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_PATH = Path('/app/workspace/stat_ocr.xlsx')

IMG_EXTS = {'.png', '.jpg', '.jpeg', '.webp', '.tif', '.tiff'}

EXCLUSION = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
]
KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

MONTHS = {
    'JAN': 1, 'JANUARY': 1,
    'FEB': 2, 'FEBRUARY': 2,
    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPT': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12,
}


def _norm_line(s: str) -> str:
    s = s.upper()
    s = re.sub(r'\s+', ' ', s).strip()
    return s


def _low_signal(text: str) -> bool:
    alnum = sum(ch.isalnum() for ch in text)
    digits = sum(ch.isdigit() for ch in text)
    return alnum < 20 or digits < 6


def ocr_bounded(img: Image.Image) -> str:
    def run(i: Image.Image, psm: int) -> str:
        return pytesseract.image_to_string(i, config=f'--oem 3 --psm {psm}')

    variants = []
    baseline = run(img, 6)
    variants.append(baseline)

    if _low_signal(baseline):
        g = ImageOps.grayscale(img)
        g = ImageOps.autocontrast(g)
        variants.append(run(g, 6))
        variants.append(run(g, 4))

    def score(t: str) -> int:
        return sum(c.isdigit() for c in t) * 2 + sum(c.isalpha() for c in t)

    return max(variants, key=score) if variants else ''


_money_token_re = re.compile(r'(?<!\d)(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?|\d+(?:\.\d{1,2})?)(?!\d)')


def _parse_money_token(tok: str) -> str | None:
    tok = tok.strip().replace(',', '')
    if tok.count('.') > 1:
        return None
    try:
        d = Decimal(tok)
    except InvalidOperation:
        return None
    if d < 0:
        return None
    return f"{d.quantize(Decimal('0.01')):.2f}"


def _amounts_in_line(line: str) -> list[str]:
    fixed = re.sub(r'(\d)\s*\.\s*(\d)', r'\1.\2', line)
    out = []
    for m in _money_token_re.finditer(fixed):
        amt = _parse_money_token(m.group(1))
        if amt is not None:
            out.append(amt)
    return out


def extract_total(text: str) -> str | None:
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    norm_lines = [_norm_line(l) for l in lines]

    def excluded(nl: str) -> bool:
        return any(k in nl for k in EXCLUSION)

    for group in KEYWORD_GROUPS:
        hits = [i for i, nl in enumerate(norm_lines) if (not excluded(nl)) and any(k in nl for k in group)]
        if not hits:
            continue

        for i in reversed(hits):
            amts = _amounts_in_line(lines[i])
            if amts:
                return amts[-1]
            if i + 1 < len(lines):
                nxt = _amounts_in_line(lines[i + 1])
                if nxt:
                    return nxt[-1]

    candidates = []
    for nl, raw in zip(norm_lines, lines):
        if excluded(nl):
            continue
        candidates.extend(_amounts_in_line(raw))
    return candidates[-1] if candidates else None


_date_ymd = re.compile(r'(?<!\d)(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})(?!\d)')
_date_dmy = re.compile(r'(?<!\d)(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2,4})(?!\d)')
_date_monthname1 = re.compile(
    r'(?<![A-Z0-9])(?P<d>\d{1,2})\s*(?P<m>JAN|JANUARY|FEB|FEBRUARY|MAR|MARCH|APR|APRIL|MAY|JUN|JUNE|JUL|JULY|AUG|AUGUST|SEP|SEPT|SEPTEMBER|OCT|OCTOBER|NOV|NOVEMBER|DEC|DECEMBER)\s*(?P<y>\d{2,4})(?!\d)',
    re.IGNORECASE,
)
_date_monthname2 = re.compile(
    r'(?<![A-Z0-9])(?P<m>JAN|JANUARY|FEB|FEBRUARY|MAR|MARCH|APR|APRIL|MAY|JUN|JUNE|JUL|JULY|AUG|AUGUST|SEP|SEPT|SEPTEMBER|OCT|OCTOBER|NOV|NOVEMBER|DEC|DECEMBER)\s*(?P<d>\d{1,2})\s*,?\s*(?P<y>\d{2,4})(?!\d)',
    re.IGNORECASE,
)


def _normalize_year(y: int) -> int:
    if y < 100:
        return 2000 + y if y <= 79 else 1900 + y
    return y


def _valid_dt(y: int, m: int, d: int) -> date | None:
    try:
        dt = date(y, m, d)
    except ValueError:
        return None
    if not (1990 <= dt.year <= 2035):
        return None
    return dt


def extract_date(text: str) -> str | None:
    lines = [l.strip() for l in text.splitlines() if l.strip()]

    near = []
    for i, l in enumerate(lines):
        nl = _norm_line(l)
        if 'DATE' in nl:
            near.append(l)
            if i + 1 < len(lines):
                near.append(lines[i + 1])

    for space in (['\n'.join(near)] if near else []) + [text]:
        if not space:
            continue

        candidates: list[date] = []
        for m in _date_ymd.finditer(space):
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
            dt = _valid_dt(y, mo, d)
            if dt:
                candidates.append(dt)

        for m in _date_dmy.finditer(space):
            a, b, y = int(m.group(1)), int(m.group(2)), _normalize_year(int(m.group(3)))
            dt1 = _valid_dt(y, b, a)  # D/M/Y
            dt2 = _valid_dt(y, a, b)  # M/D/Y
            if dt1 and dt2:
                candidates.append(dt1)
            elif dt1:
                candidates.append(dt1)
            elif dt2:
                candidates.append(dt2)

        for m in _date_monthname1.finditer(space):
            d = int(m.group('d'))
            mo = MONTHS[_norm_line(m.group('m'))]
            y = _normalize_year(int(m.group('y')))
            dt = _valid_dt(y, mo, d)
            if dt:
                candidates.append(dt)

        for m in _date_monthname2.finditer(space):
            d = int(m.group('d'))
            mo = MONTHS[_norm_line(m.group('m'))]
            y = _normalize_year(int(m.group('y')))
            dt = _valid_dt(y, mo, d)
            if dt:
                candidates.append(dt)

        if candidates:
            return candidates[0].isoformat()

    return None


def main() -> None:
    img_files = sorted([p for p in IMG_DIR.iterdir() if p.is_file() and p.suffix.lower() in IMG_EXTS], key=lambda p: p.name)
    if not img_files:
        raise SystemExit(f'No images found under {IMG_DIR}')

    try:
        _ = pytesseract.get_tesseract_version()
        tesseract_ok = True
    except Exception:
        tesseract_ok = False

    rows = []
    for p in img_files:
        dt = None
        total = None

        if tesseract_ok:
            try:
                with Image.open(p) as im:
                    im = im.convert('RGB')
                    text = ocr_bounded(im)
            except Exception:
                text = ''

            if text:
                dt = extract_date(text)
                total = extract_total(text)

        rows.append((p.name, dt, total))

    # Write workbook: exactly one sheet named results.
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'

    ws.append(['filename', 'date', 'total_amount'])
    for filename, dt, total in rows:
        ws.append([filename, dt, total])

    # Ensure no extra sheets.
    for name in list(wb.sheetnames):
        if name != 'results':
            del wb[name]

    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    wb.save(OUT_PATH)

    # Post-write validation
    wb2 = load_workbook(OUT_PATH)
    assert wb2.sheetnames == ['results'], f"Expected one sheet 'results', got {wb2.sheetnames}"
    ws2 = wb2['results']

    header = [ws2.cell(row=1, column=c).value for c in range(1, 4)]
    assert header == ['filename', 'date', 'total_amount'], f'Bad header: {header}'

    data = []
    for r in range(2, ws2.max_row + 1):
        data.append(ws2.cell(row=r, column=1).value)
    assert data == sorted(data), 'Rows are not sorted by filename'


if __name__ == '__main__':
    main()
    print(OUT_PATH)
